import Image from "next/image";

import { asset } from "@/lib/asset";
import { images, type ImageKey } from "@/lib/images";

type Ratio = "portrait" | "tall" | "square" | "landscape" | "wide" | "auto";

const ratioClass: Record<Ratio, string> = {
  portrait: "aspect-[4/5]",
  tall: "aspect-[3/4.4]",
  square: "aspect-square",
  landscape: "aspect-[4/3]",
  wide: "aspect-[16/10]",
  auto: "",
};

/**
 * Editorial image. Fixed aspect box + object-cover, so nothing shifts while
 * the file loads. Blur placeholders are generated by scripts/images.py.
 */
export function EditorialImage({
  image,
  alt,
  ratio = "portrait",
  sizes = "(min-width: 1024px) 33vw, (min-width: 640px) 50vw, 100vw",
  priority = false,
  className = "",
  imageClassName = "",
}: {
  image: ImageKey;
  alt: string;
  ratio?: Ratio;
  sizes?: string;
  priority?: boolean;
  className?: string;
  imageClassName?: string;
}) {
  const meta = images[image];

  return (
    <div
      className={`relative overflow-hidden bg-sand ${ratioClass[ratio]} ${className}`}
    >
      <Image
        src={asset(meta.src)}
        alt={alt}
        fill
        sizes={sizes}
        priority={priority}
        loading={priority ? undefined : "lazy"}
        placeholder="blur"
        blurDataURL={meta.blurDataURL}
        className={`img-hover object-cover ${imageClassName}`}
      />
    </div>
  );
}

/**
 * Rendered wherever no photograph has been supplied yet. Deliberately visible:
 * it states what is needed rather than pretending to be a design element.
 */
export function ImageSlot({
  brief,
  ratio = "portrait",
  className = "",
  label = "Image to be supplied",
}: {
  brief: string;
  ratio?: Ratio;
  className?: string;
  label?: string;
}) {
  return (
    <div
      className={`relative flex flex-col justify-end overflow-hidden border border-dashed border-olive/35 bg-sand-light ${ratioClass[ratio]} ${className}`}
    >
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 opacity-[0.5]"
        style={{
          backgroundImage:
            "repeating-linear-gradient(135deg, transparent 0 11px, color-mix(in srgb, var(--color-olive) 9%, transparent) 11px 12px)",
        }}
      />
      <div className="relative p-6 sm:p-7">
        <p className="eyebrow text-olive">{label}</p>
        <p className="mt-3 max-w-[34ch] font-display text-[1.35rem] leading-snug text-charcoal/75">
          {brief}
        </p>
      </div>
    </div>
  );
}

/**
 * Picks the right one. Keeps every call site free of null checks.
 */
export function MediaFrame({
  image,
  alt,
  brief,
  ratio = "portrait",
  sizes,
  priority,
  className = "",
}: {
  image: ImageKey | null;
  alt: string;
  brief: string;
  ratio?: Ratio;
  sizes?: string;
  priority?: boolean;
  className?: string;
}) {
  if (!image) {
    return <ImageSlot brief={brief} ratio={ratio} className={className} />;
  }
  return (
    <EditorialImage
      image={image}
      alt={alt}
      ratio={ratio}
      sizes={sizes}
      priority={priority}
      className={className}
    />
  );
}
